// Generated by ../../../rebuild.py; one topology per leaf.
use rand::{rngs::StdRng, Rng};
use std::f64::consts::PI;

fn pick(rng: &mut StdRng, values: &[f64]) -> f64 {
    values[rng.random_range(0..values.len())]
}

pub fn generate(rng: &mut StdRng) -> String {

    let l = pick(rng, &[1e-3, 4.7e-3, 10e-3, 47e-3]);
    let c = pick(rng, &[1e-9, 4.7e-9, 10e-9, 47e-9, 100e-9, 1e-6]);
    let zeta = pick(rng, &[0.25, 0.5, 0.707, 1.0, 1.5]);
    let r = 2.0 * zeta * (l / c).sqrt();
    let f0 = 1.0 / (2.0 * PI * (l * c).sqrt());
    let q = 1.0 / (2.0 * zeta);
    let period = 1.0 / f0;
    format!("Series RLC band-pass filter\n* Ideal source and parts; unloaded output; values in SI.\n* Natural frequency {f0:.5e} Hz; damping ratio {zeta}; Q={q:.5e}.\n* H(s)=s*R*C/(1+s*R*C+s^2*L*C).\nV1 in 0 DC 0 AC 1 PULSE(0 1 0 {:.5e} {:.5e} {:.5e} {:.5e})\nC1 in mid {c:.5e}\nL1 mid out {l:.5e}\nR1 out 0 {r:.5e}\n.op\n.ac dec 40 {:.5e} {:.5e}\n.tran {:.5e} {:.5e}\n.print ac vm(out) vp(out)\n.print tran v(in) v(out)\n.end", period / 1000.0, period / 1000.0, period * 10.0, period * 20.0, f0 / 100.0, f0 * 100.0, period / 200.0, period * 40.0)
}

#[cfg(test)]
mod validate;

#[cfg(test)]
mod tests {
    use super::*;
    use rand::SeedableRng;

    #[test]
    fn independent_nodal_analysis_matches_topology() {
        let mut rng = StdRng::seed_from_u64(47);
        for _ in 0..200 {
            validate::verify(&generate(&mut rng), "rlc-band-pass");
        }
    }
}
